    10	  for (const coupon of coupons) {
    11	    if (coupon.type === 'percent') totalMinor -= Math.round((totalMinor * coupon.value) / 100);
    12	    else totalMinor -= coupon.value;
    13	  }
    14	  return { subtotalMinor, discountMinor: subtotalMinor - totalMinor, totalMinor };
