    10	    this.stock = stock;
    11	    this.clock = clock;
    12	    this.audit = audit;
    13	    this.reservations = new Map();
    14	  }
    15	
    16	  adjustHeld(reservation, sign) {
    17	    for (const line of reservation.lines)
    18	      this.stock.level(reservation.sku, line.warehouse).held += sign * line.quantity;
    19	  }
    20	
    21	  expireDue() {
    22	    const now = this.clock();
    23	    for (const reservation of this.reservations.values()) {
    24	      if (reservation.status === 'held' && now > reservation.expiresAt) {
    25	        reservation.status = 'expired';
    26	        this.adjustHeld(reservation, -1);
    27	        this.audit.record({ type: 'expired', reservationId: reservation.id, at: now });
    28	      }
    29	    }
    30	  }
    31	
    32	  available(sku) {
    33	    this.expireDue();
    34	    return this.stock
    35	      .forSku(sku)
    36	      .reduce((total, level) => total + Math.max(0, level.onHand - level.held), 0);
    37	  }
    38	
    39	  reserve(request) {
    40	    const { orderId, sku, quantity, customerTier = 'standard' } = request ?? {};
    41	    if (!validString(orderId) || !validString(sku)) throw new Error('invalid_request');
    42	    if (!(quantity > 0)) throw new Error('invalid_quantity');
    43	    this.expireDue();
    44	    const { lines, backorderQuantity } = allocate(this.stock.forSku(sku), quantity);
    45	    const now = this.clock();
    46	    const reservation = {
    47	      id: 'res_' + (this.reservations.size + 1),
    48	      orderId,
    49	      sku,
    50	      lines,
    51	      backorderQuantity,
    52	      status: 'held',
    53	      expiresAt: now + HOLD_TTL_MS,
    54	    };
    55	    this.reservations.set(reservation.id, reservation);
    56	    this.adjustHeld(reservation, 1);
    57	    this.audit.record({ type: 'reserved', reservationId: reservation.id, at: now });
    58	    return structuredClone(reservation);
    59	  }
