    66	      this.adjustHeld(reservation, -1);
    67	      return structuredClone(reservation);
    68	    }
    69	    if (reservation.status !== 'held') return structuredClone(reservation);
    70	    reservation.status = 'released';
    71	    this.adjustHeld(reservation, -1);
    72	    this.audit.record({ type: 'released', reservationId: id, at: this.clock() });
    73	    return structuredClone(reservation);
    74	  }
